(function(){
  "use strict";
var D = {
"front_circuit_housing":"",
"main_knob_house":"",
"storage_bracket_left":"",
"storage_bracket_right":"",
"flow_base_plate":"",
"flow_hemispherical_part":"",
"flow_click_generator":"",
"flow_gear_hub":"",
"flow_cable_holder":"",
"flow_cable_holder_cover":"",
"temp_hemispherical_part":"",
"temp_knob_rod":"",
"temp_potentiometer_holder":"",
"temp_potentiometer":""
};;
  var PART_KEYS = [
    "front_circuit_housing", "main_knob_house", "storage_bracket_left", "storage_bracket_right",
    "flow_base_plate", "flow_hemispherical_part", "flow_click_generator", "flow_gear_hub",
    "flow_cable_holder", "flow_cable_holder_cover",
    "temp_hemispherical_part", "temp_knob_rod", "temp_potentiometer_holder", "temp_potentiometer"
  ];

  var MODEL_DATA = { assembly: PART_KEYS.map(function(k){ return { part: k, data: D[k] }; }) };
  PART_KEYS.forEach(function(k){ MODEL_DATA[k] = [ { part: k, data: D[k] } ]; });

  var MODEL_CAPTIONS = {
    assembly: 'The full relocated climate-control structure: 14 parts across three groups: shared common parts, the airflow-direction control side (kept its cable-actuated mechanism), and the temperature-control side (converted to servo + potentiometer control).',
    front_circuit_housing: 'Common part. Encloses and locates circuitry/wiring for the front-facing control cluster.',
    main_knob_house: 'Common part. Shared housing structure that both control knobs mount through.',
    storage_bracket_left: 'Common part. Structural bracket tying the storage bay to the relocated A/C box.',
    storage_bracket_right: 'Common part. Mirrored bracket for the right side of the same joint.',
    flow_base_plate: 'Airflow-direction control side. Structural base the rest of this sub-assembly builds on.',
    flow_hemispherical_part: 'Airflow-direction control side. Outer housing shell that seats against the dash.',
    flow_click_generator: 'Airflow-direction control side. Produces the tactile click feel as the vent-direction knob is turned.',
    flow_gear_hub: 'Airflow-direction control side. Gear interface translating knob rotation into the mechanism\'s motion.',
    flow_cable_holder: 'Airflow-direction control side. Retains and routes the relocated actuator cable.',
    flow_cable_holder_cover: 'Airflow-direction control side. Closes over the cable holder to keep the run captured.',
    temp_hemispherical_part: 'Temperature-control side. Outer housing shell on this side.',
    temp_knob_rod: 'Temperature-control side. Interface rod linking the dash-facing knob to the internal mechanism.',
    temp_potentiometer_holder: 'Temperature-control side. Mounts the potentiometer that replaces the stock cable mechanism.',
    temp_potentiometer: 'Temperature-control side. The servo-control sensing component itself, seated in the holder in place of the stock cable takeoff.'
  };

  // Download link labels use the same names as the viewer tabs
  function tabLabel(k){
    var t = document.querySelector('.viewer-tab[data-model="' + k + '"]');
    return t ? t.textContent.trim() : k.replace(/_/g, ' ');
  }
  var MODEL_DOWNLOADS = { assembly: [ { label: 'Full SolidWorks source (.zip)', href: 'cad-source.zip' } ] };
  PART_KEYS.forEach(function(k){
    MODEL_DOWNLOADS[k] = [ { label: tabLabel(k) + ' (.stl)', href: 'stl/' + k + '.stl' } ];
  });

  function decodePositions(b64){
    var bin = atob(b64);
    var len = bin.length;
    var buf = new ArrayBuffer(len);
    var bytes = new Uint8Array(buf);
    for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Float32Array(buf);
  }

  function rawGeometry(b64){
    var positions = decodePositions(b64);
    var geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.computeVertexNormals();
    geo.computeBoundingBox();
    return geo;
  }

  function buildAssembly(parts){
    var built = parts.map(function(p){ return { part: p, geo: rawGeometry(p.data) }; });
    var box = new THREE.Box3();
    built.forEach(function(b){ box.union(b.geo.boundingBox); });
    var center = new THREE.Vector3();
    box.getCenter(center);
    built.forEach(function(b){ b.geo.translate(-center.x, -center.y, -center.z); });
    var sphere = new THREE.Sphere();
    box.getBoundingSphere(sphere);
    return { parts: built, boundingSphere: sphere };
  }

  var canvas = document.getElementById('stl-canvas');
  var loadingEl = document.getElementById('viewer-loading');
  var captionEl = document.getElementById('viewer-caption');
  var downloadsEl = document.getElementById('viewer-downloads');
  var stage = canvas.parentElement;

  var renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));

  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(35, 1, 0.1, 5000);

  var key = new THREE.DirectionalLight(0xffffff, 1.1);
  key.position.set(4, 6, 6);
  scene.add(key);
  var fill = new THREE.DirectionalLight(0x6a86ff, 0.35);
  fill.position.set(-5, -2, -4);
  scene.add(fill);
  scene.add(new THREE.AmbientLight(0xffffff, 0.7));

  var group = new THREE.Group();
  group.rotation.x = -Math.PI / 2; /* CAD Z-up -> three.js Y-up */
  scene.add(group);

  var material = new THREE.MeshStandardMaterial({ color: 0x9aa1a8, roughness: 0.55, metalness: 0.05 });
  var meshes = [];
  var geometries = {};

  var rotY = 0.6, rotX = -0.28, camDist = 3, minDist = 1, maxDist = 12;
  var dragging = false, lastX = 0, lastY = 0, lastInteract = 0;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var w = stage.clientWidth, h = stage.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  if (window.ResizeObserver) new ResizeObserver(resize).observe(stage);

  function frameCameraRadius(r){
    r = r || 1;
    camDist = r * 2.6;
    minDist = r * 1.2;
    maxDist = r * 6;
  }

  function clearMeshes(){
    meshes.forEach(function(m){
      group.remove(m);
      if (m.material !== material) m.material.dispose();
    });
    meshes = [];
  }

  function showModel(k){
    var entry = geometries[k];
    if (!entry) return;
    clearMeshes();
    entry.parts.forEach(function(b){
      var m = new THREE.Mesh(b.geo, material);
      group.add(m);
      meshes.push(m);
    });
    frameCameraRadius(entry.boundingSphere.radius);
    var capEls = captionEl.querySelectorAll('[data-model]');
    if (capEls.length) { for (var ci = 0; ci < capEls.length; ci++) capEls[ci].hidden = capEls[ci].getAttribute('data-model') !== k; }
    else captionEl.textContent = MODEL_CAPTIONS[k];
    var files = MODEL_DOWNLOADS[k] || [];
    downloadsEl.innerHTML = files.map(function(f){
      return '<a href="' + f.href + '" download>&#8681; ' + f.label + '</a>';
    }).join('');
  }

  function updateCamera(){
    camera.position.set(
      camDist * Math.sin(rotY) * Math.cos(rotX),
      camDist * Math.sin(rotX),
      camDist * Math.cos(rotY) * Math.cos(rotX)
    );
    camera.lookAt(0, 0, 0);
  }

  canvas.addEventListener('pointerdown', function(e){
    dragging = true; lastX = e.clientX; lastY = e.clientY;
    canvas.setPointerCapture(e.pointerId);
    lastInteract = performance.now();
  });
  canvas.addEventListener('pointerup', function(){ dragging = false; });
  canvas.addEventListener('pointercancel', function(){ dragging = false; });
  canvas.addEventListener('pointermove', function(e){
    if (!dragging) return;
    var dx = e.clientX - lastX, dy = e.clientY - lastY;
    lastX = e.clientX; lastY = e.clientY;
    rotY += dx * 0.008;
    rotX = Math.max(-1.3, Math.min(1.3, rotX - dy * 0.008));
    lastInteract = performance.now();
  });
  canvas.addEventListener('wheel', function(e){
    e.preventDefault();
    camDist = Math.max(minDist, Math.min(maxDist, camDist * (1 + e.deltaY * 0.0015)));
    lastInteract = performance.now();
  }, { passive: false });

  document.querySelectorAll('.viewer-tab').forEach(function(btn){
    btn.addEventListener('click', function(){
      document.querySelectorAll('.viewer-tab').forEach(function(b){
        b.classList.remove('is-active'); b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('is-active'); btn.setAttribute('aria-selected', 'true');
      rotY = 0.6; rotX = -0.28;
      showModel(btn.dataset.model);
    });
  });

  // Links in the text like <a href="#viewer" data-viewer-tab="KEY"> open that model in the viewer
  document.addEventListener('click', function(e){
    var link = e.target.closest && e.target.closest('[data-viewer-tab]');
    if (!link || document.body.hasAttribute('data-ed-on')) return;
    var tab = document.querySelector('.viewer-tab[data-model="' + link.getAttribute('data-viewer-tab') + '"]');
    if (!tab) return;
    e.preventDefault();
    tab.click();
    var target = document.getElementById('viewer') || tab;
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  function animate(){
    requestAnimationFrame(animate);
    if (!dragging && !reduceMotion && performance.now() - lastInteract > 2200){
      rotY += 0.0016;
    }
    updateCamera();
    renderer.render(scene, camera);
  }

  Object.keys(MODEL_DATA).forEach(function(k){
    geometries[k] = buildAssembly(MODEL_DATA[k]);
  });
  loadingEl.hidden = true;
  resize();
  showModel('assembly');
  animate();
})();
